<?php
namespace App\Http\Controllers;
use App\Models\{Timetable,User}; use App\Services\TimetableConflictService; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class TimetableController extends Controller { public function index(Request $r){$q=Timetable::with('teacher')->when($r->day,fn($x,$v)=>$x->where('day',$v))->when($r->teacher_id,fn($x,$v)=>$x->where('teacher_id',$v));if($r->user()->role==='teacher')$q->where('teacher_id',$r->user()->id);$items=$q->orderBy('day')->orderBy('start_time')->paginate(20)->withQueryString();$teachers=User::teachers()->active()->get();return view('timetables.index',compact('items','teachers'));} public function create(){return view('timetables.form',['timetable'=>new Timetable,'teachers'=>User::teachers()->active()->get()]);} public function store(Request $r,TimetableConflictService $s){$d=$this->valid($r);if($s->exists($d))return back()->withInput()->withErrors(['start_time'=>'Timetable conflict detected.']);$d['admin_id']=$r->user()->id;Timetable::create($d);return redirect()->route('admin.timetables.index')->with('success','Timetable saved successfully.');} public function edit(Timetable $timetable){return view('timetables.form',['timetable'=>$timetable,'teachers'=>User::teachers()->active()->get()]);} public function update(Request $r,Timetable $timetable,TimetableConflictService $s){$d=$this->valid($r);if($s->exists($d,$timetable->id))return back()->withInput()->withErrors(['start_time'=>'Timetable conflict detected.']);$timetable->update($d);return back()->with('success','Timetable saved successfully.');} public function destroy(Timetable $timetable){$timetable->delete();return back()->with('success','Timetable deleted successfully.');} private function valid(Request $r){return $r->validate(['teacher_id'=>['required',Rule::exists('users','id')->where(fn($q)=>$q->where('role','teacher')->where('is_active',true))],'day'=>['required',Rule::in(['Sun','Mon','Tue','Wed','Thu'])],'start_time'=>'required|date_format:H:i','end_time'=>'required|date_format:H:i|after:start_time','classroom'=>'required|string|max:100','subject'=>'required|string|max:100']);}}
